/**
 * @suppress
 */
public object FfiConverterTypeLightNode: FfiConverter<LightNode, Long> {
    override fun lower(value: LightNode): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): LightNode {
        return LightNode(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): LightNode {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: LightNode) = 8UL

    override fun write(value: LightNode, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * A summary of one block in this node's DAG — enough for wallets to render
 * history without holding payloads.
 */
data class BlockInfo (
    /**
     * BLAKE3 block id, lowercase hex (commits to parents+work+ts+nonce+payload).
     */
    var `idHex`: kotlin.String
    , 
    /**
     * Parent ids, lowercase hex (sorted, de-duplicated, as `Block` stores them).
     */
    var `parentsHex`: List<kotlin.String>
    , 
    /**
     * Which hybrid admission path produced it.
     */
    var `kind`: BlockKind
    , 
    /**
     * Claimed work weight (nominal `1` for staked blocks).
     */
    var `work`: U128Parts
    , 
    /**
     * Milliseconds since the UNIX epoch.
     */
    var `timestampMs`: kotlin.ULong
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBlockInfo: FfiConverterRustBuffer<BlockInfo> {
    override fun read(buf: ByteBuffer): BlockInfo {
        return BlockInfo(
            FfiConverterString.read(buf),
            FfiConverterSequenceString.read(buf),
            FfiConverterTypeBlockKind.read(buf),
            FfiConverterTypeU128Parts.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: BlockInfo) = (
            FfiConverterString.allocationSize(value.`idHex`) +
            FfiConverterSequenceString.allocationSize(value.`parentsHex`) +
            FfiConverterTypeBlockKind.allocationSize(value.`kind`) +
            FfiConverterTypeU128Parts.allocationSize(value.`work`) +
            FfiConverterULong.allocationSize(value.`timestampMs`)
    )

    override fun write(value: BlockInfo, buf: ByteBuffer) {
            FfiConverterString.write(value.`idHex`, buf)
            FfiConverterSequenceString.write(value.`parentsHex`, buf)
            FfiConverterTypeBlockKind.write(value.`kind`, buf)
            FfiConverterTypeU128Parts.write(value.`work`, buf)
            FfiConverterULong.write(value.`timestampMs`, buf)
    }
}



/**
 * Genesis parameters for a fresh light node.
 */
data class LightConfig (
    /**
     * GHOSTDAG parameter `k` (merge depth).
     */
    var `k`: kotlin.UShort
    , 
    /**
     * Per-block KVNC subsidy.
     */
    var `subsidy`: kotlin.ULong
    , 
    /**
     * Genesis coinbase size minted to the founder actor.
     */
    var `founderAmount`: kotlin.ULong
    , 
    /**
     * Founder actor seed (deterministic demo keys; real wallets keep custody
     * client-side — see module docs).
     */
    var `founderSeed`: kotlin.ULong
    , 
    /**
