     */
    var `finalityDepth`: kotlin.ULong
    , 
    /**
     * Payload pruning depth; keep ≥ `finality_depth`.
     */
    var `payloadPruningDepth`: kotlin.ULong
    
){
    

    

    
    companion object
}

