/**
 * @suppress
 */
public object FfiConverterTypeBlockKind: FfiConverterRustBuffer<BlockKind> {
    override fun read(buf: ByteBuffer) = try {
        BlockKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: BlockKind) = 4UL

    override fun write(value: BlockKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Why a [`LightNode`] operation failed.
 */
sealed class LightNodeException: kotlin.Exception() {
    
    class AlreadyInitialized(
        ) : LightNodeException() {
        override val message
            get() = ""
    }
    
    class Hex(
        
        val `field`: kotlin.String
        ) : LightNodeException() {
        override val message
            get() = "field=${ `field` }"
    }
    
    class BadSeedLength(
        ) : LightNodeException() {
        override val message
            get() = ""
    }
    
    class Invalid(
        
        val `msg`: kotlin.String
        ) : LightNodeException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InsufficientFunds(
        
        val `needed`: kotlin.ULong
        ) : LightNodeException() {
        override val message
            get() = "needed=${ `needed` }"
    }
    
    class BadSecretLength(
        
        val `expected`: kotlin.UInt, 
        
        val `got`: kotlin.UInt
        ) : LightNodeException() {
        override val message
            get() = "expected=${ `expected` }, got=${ `got` }"
    }
    
    class InsufficientStake(
        
        val `requested`: kotlin.ULong, 
        
        val `available`: kotlin.ULong
        ) : LightNodeException() {
        override val message
            get() = "requested=${ `requested` }, available=${ `available` }"
    }
    
    class Node(
        
        val `msg`: kotlin.String
        ) : LightNodeException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LightNodeException> {
        override fun lift(error_buf: RustBuffer.ByValue): LightNodeException = FfiConverterTypeLightNodeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLightNodeError : FfiConverterRustBuffer<LightNodeException> {
    override fun read(buf: ByteBuffer): LightNodeException {
        

        return when(buf.getInt()) {
            1 -> LightNodeException.AlreadyInitialized()
            2 -> LightNodeException.Hex(
                FfiConverterString.read(buf),
                )
            3 -> LightNodeException.BadSeedLength()
            4 -> LightNodeException.Invalid(
                FfiConverterString.read(buf),
                )
            5 -> LightNodeException.InsufficientFunds(
                FfiConverterULong.read(buf),
                )
            6 -> LightNodeException.BadSecretLength(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            7 -> LightNodeException.InsufficientStake(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            8 -> LightNodeException.Node(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LightNodeException): ULong {
        return when(value) {
            is LightNodeException.AlreadyInitialized -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LightNodeException.Hex -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
            )
            is LightNodeException.BadSeedLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LightNodeException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is LightNodeException.InsufficientFunds -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`needed`)
            )
            is LightNodeException.BadSecretLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`expected`)
                + FfiConverterUInt.allocationSize(value.`got`)
            )
            is LightNodeException.InsufficientStake -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`requested`)
                + FfiConverterULong.allocationSize(value.`available`)
            )
            is LightNodeException.Node -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: LightNodeException, buf: ByteBuffer) {
        when(value) {
            is LightNodeException.AlreadyInitialized -> {
                buf.putInt(1)
                Unit
            }
            is LightNodeException.Hex -> {
                buf.putInt(2)
                FfiConverterString.write(value.`field`, buf)
                Unit
            }
            is LightNodeException.BadSeedLength -> {
                buf.putInt(3)
                Unit
            }
            is LightNodeException.Invalid -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is LightNodeException.InsufficientFunds -> {
                buf.putInt(5)
                FfiConverterULong.write(value.`needed`, buf)
                Unit
            }
            is LightNodeException.BadSecretLength -> {
                buf.putInt(6)
                FfiConverterUInt.write(value.`expected`, buf)
                FfiConverterUInt.write(value.`got`, buf)
                Unit
            }
            is LightNodeException.InsufficientStake -> {
                buf.putInt(7)
                FfiConverterULong.write(value.`requested`, buf)
                FfiConverterULong.write(value.`available`, buf)
                Unit
            }
            is LightNodeException.Node -> {
                buf.putInt(8)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalULong: FfiConverterRustBuffer<kotlin.ULong?> {
    override fun read(buf: ByteBuffer): kotlin.ULong? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterULong.read(buf)
    }

    override fun allocationSize(value: kotlin.ULong?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterULong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.ULong?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterULong.write(value, buf)
        }
    }
}




